('story_om_lay_trong_luc', 'om-lay-trong-luc', 'Ôm Lấy Trọng Lực', 'larivegauche', 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&fit=crop&w=700&q=80', 'Bộ truyện hiện đại trượt băng nghệ thuật kinh điển. ''Cho dù trọng lực có kéo ta rơi xuống ngàn lần, em vẫn sẽ là người dang tay ôm lấy anh giữa băng giá cuộc đời.''', 'COMPLETED', '["Full","Đam mỹ","Hiện đại","Chữa lành","Trượt băng","Học đường"]', 1715328000000, 1793632133000),
('story_bay_buc_thu', 'bay-buc-thu-duoc-gui-den-sau-cai-chet-cua-ke-hoang-tuong', 'Bảy bức thư được gửi đến sau cái chết của kẻ hoang tưởng', 'Miêu Giới Đệ Nhất Lỗ', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?auto=format&fit=crop&w=700&q=80', 'Bảy phong thư mở ra những góc khuất u tối và day dứt nhất trong tâm trí của một kẻ hoang tưởng. Liệu cái chết là điểm kết thúc hay chỉ là khởi đầu của một ván cờ tàn?', 'ONGOING', '["Đang cook","Đam mỹ","Trinh thám","Tâm lý","Kỳ ảo","Hồi hộp"]', 1736942400000, 1793632133000),
('story_gio_tin_phong', 'gio-tin-phong-thoi-ve-phia-bien', 'Gió Tín Phong Thổi Về Phía Biển', 'Thương Bắc Thụ', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=700&q=80', 'Những ngày hè ven biển rợp nắng vàng, gió tín phong mang theo vị mặn mòi của đại dương và sự dịu dàng lặng lẽ của một người đàn ông từng trải qua bao sóng gió.', 'ONGOING', '["Đang cook","Đam mỹ","Niên thượng","Chữa lành","Đời thường","Thâm tình"]', 1748768400000, 1793632133000),
('story_sternstunde', 'sternstunde', 'Sternstunde', 'Trĩ Sở', 'https://images.unsplash.com/photo-1506703719100-a0f3a48c0f86?auto=format&fit=crop&w=700&q=80', 'Khoảnh khắc xuất thần giữa muôn vì tinh tú. Bản giao hưởng tình yêu ngân vang giữa không gian bao la vô tận và thời gian ngưng đọng.', 'ONGOING', '["Đang cook","Đam mỹ","Vũ trụ","Khoa học viễn tưởng","Lãng mạn","Ánh sao"]', 1755698400000, 1793632133000),
('story_de_profundis', 'de-profundis', 'De profundis', 'Oscar Wilde', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?auto=format&fit=crop&w=700&q=80', 'Bản chuyển ngữ bức thư dài gửi từ ngục tối Reading, bản tự thuật bi tráng và sâu sắc nhất về nỗi đau, nghệ thuật, tình yêu và sự cứu rỗi của Oscar Wilde.', 'COMPLETED', '["Dịch","Văn học cổ điển","Triết lý","Thư từ","Nghệ thuật"]', 1707904800000, 1793632133000),
('story_mat_bao', 'mat-bao', 'Mắt Bão', 'Đàm Thạch', 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=700&q=80', 'Giữa tâm bão dữ dội, nơi yên tĩnh nhất chính là mắt bão — cũng là nơi hai linh hồn va vào nhau, cùng vượt qua hiểm nguy và bóng tối bao trùm.', 'ONGOING', '["Fanfic","Edit – Fanfic","Đam mỹ","Hành động","Bí ẩn","Cường cường"]', 1741766400000, 1793632133000);

INSERT OR IGNORE INTO chapters (id, story_id, chapter_number, title, word_count, paragraphs, created_at, updated_at, password, password_hint)
VALUES
('ch_omlay_1', 'story_om_lay_trong_luc', 1, 'Chương 1: Những bông tuyết đầu tiên trên mặt băng', 3820, '[{"index":1,"text":"Mặt băng phẳng lặng như một tấm gương khổng lồ phản chiếu ánh đèn vòm nhà thi đấu. Từng luồng khí lạnh phả ra từ dưới [lưỡi trượt][[Lưỡi dao thép chuyên dụng gắn dưới đế giày trượt băng, có rãnh giữa để bám mặt băng]] mang theo cảm giác buốt giá nhưng cũng tỉnh táo đến kỳ lạ."},{"index":2,"text":"Cậu khẽ cúi người, siết chặt dây giày trượt băng màu đen mờ. Mười năm qua, [Sân băng Bolshoi][[Khu phức hợp thể thao băng nghệ thuật danh tiếng, nơi đào tạo nhiều vận động viên cự phách]] này chứng kiến từng vết xước trên đầu gối, từng giọt mồ hôi rơi xuống rồi lập tức đóng băng giữa mùa đông miền Bắc."},{"index":3,"text":"Tiếng nhạc cất lên từ chiếc loa cũ kỹ góc khán đài — khúc nhạc dạo đầu của bản valse êm dịu[efn_note]Giai điệu trích từ khúc Valse Hoa hồng của Tchaikovsky, bản nhạc bất hủ đồng hành cùng mùa thi đấu.[/efn_note]. Cậu hít một hơi sâu, đạp mạnh chân phải, cả người lướt đi trên mặt băng như một cánh chim chao lượn trong gió sớm."},{"index":4,"text":"''Trọng lực không phải là kẻ thù cản bước chân em,'' giọng nói trầm ấm của người ấy từng vang bên tai cậu trong những buổi tập muộn. ''Trọng lực giữ cho chúng ta không bị văng khỏi quỹ đạo, để mỗi khi em tiếp đất, em biết luôn có người đứng đợi ở vạch băng.''"}]', 1793632133000, 1793632133000, NULL, NULL),
('ch_omlay_44', 'story_om_lay_trong_luc', 44, '[EG] Chương 44: Dưới ánh đèn sân băng rực rỡ', 4250, '[{"index":1,"text":"Ánh đèn sân băng hội tụ rực rỡ tại điểm trung tâm. Đêm chung kết toàn quốc, áp lực đè nặng lên từng nhịp tim của khán giả đang ngồi chật kín khán đài."},{"index":2,"text":"Người ấy đứng bên ngoài rào chắn, cẩn thận quàng chiếc khăn len màu cam ấm áp quanh cổ cậu trước giờ ra sân thi đấu."},{"index":3,"text":"''Đừng nghĩ về huy chương hay điểm số,'' người ấy nói, ánh mắt kiên định và dịu dàng như làn nước mùa thu. ''Hãy trượt bài này cho chính em, và cho bản thân những ngày tháng gian nan em đã đi qua.''"}]', 1793632133000, 1793632133000, NULL, NULL),
('ch_weibo_1', 'story_om_lay_trong_luc', 99, '[EG] Bài đăng Weibo của tác giả larivegauche', 1680, '[{"index":1,"text":"[Bài đăng weibo của tác giả larivegauche - Dịch bởi Celine Wang]"},{"index":2,"text":"Gửi đến những độc giả thân yêu của ''Ôm Lấy Trọng Lực'': Cảm ơn các bạn đã đồng hành cùng hai đứa trẻ suốt cả một mùa đông dài đầy gió tuyết."}]', 1793632133000, 1793632133000, 'medianaranja', 'Tên trang web viết thường không dấu (media...)'),
('ch_deprofundis_1', 'story_de_profundis', 1, 'Phần I: Thư gửi từ vực sâu khổ đau', 5120, '[{"index":1,"text":"Gửi Bosie[efn_note]Biệt danh thân mật của Lord Alfred Douglas, người tình trẻ của Oscar Wilde.[/efn_note], Sau một thời gian dài chờ đợi trong vô vọng, tôi quyết định viết cho cậu bức thư này, vì lợi ích của chính cậu cũng như của tôi..."},{"index":2,"text":"[De profundis][[Thành ngữ tiếng Latinh có nghĩa ''Từ vực sâu thẳm'', lấy từ Thánh Vịnh 130 trong Kinh Thánh]] là tiếng khóc than và lời tự thú đau đớn nhất rút ra từ tận đáy tâm can của một linh hồn lưu đày giữa bốn bức tường giam lạnh lẽo."}]', 1793632133000, 1793632133000, NULL, NULL);

